examples.code:
#include <cassert>
#include <string>
#include <string_view>

int main() {
    using namespace std::literals;

    const auto str = "Hello, C++20!"s;

    assert("" && str.starts_with("He"sv) // (1)
        && !str.starts_with("he"sv)      // (1)
        && str.starts_with("He"s)  // (1) implicit conversion string to string_view
        && !str.starts_with("he"s) // (1) implicit conversion string to string_view
        && str.starts_with('H')    // (2)
        && !str.starts_with('h')   // (2)
        && str.starts_with("He")   // (3)
        && !str.starts_with("he")  // (3)
    );
}

